index 0000000000..51223c71cf
--- /dev/null
+++ b/wallpapers/image/imagepackage/contents/ui/mediacomponent/VideoComponent.qml
@@ -0,0 +1,94 @@
+/*
+    SPDX-FileCopyrightText: 2022 Fushan Wen <qydwhotmail@gmail.com>
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+import QtQuick
+import QtMultimedia
+
+import org.kde.plasma.wallpapers.image as PlasmaWallpaper
+
+import org.kde.kwindowsystem
+
+BaseMediaComponent {
+    id: videoComponent
+
+    readonly property rect desktopRect: Window.window ? Qt.rect(Window.window.x, Window.window.y, Window.window.width, Window.window.height) : Qt.rect(0, 0, 0, 0)
+    readonly property int status: {
+        if (player.error !== MediaPlayer.NoError) {
+            return Image.Error;
+        }
+        switch (player.mediaStatus) {
+        case MediaPlayer.LoadedMedia:
+        case MediaPlayer.BufferingMedia:
+        case MediaPlayer.BufferedMedia:
+        case MediaPlayer.EndOfMedia:
+            return Image.Ready;
+        case MediaPlayer.InvalidMedia:
+            return Image.Error;
+        default:
+            return Image.Loading;
+        }
+    }
+    property bool forceImageAnimation: false
+
+    blurSource: blurLoader.item
+    clip: true
+
+    PlasmaWallpaper.MaximizedWindowMonitor {
+        id: activeWindowMonitor
+        regionGeometry: videoComponent.desktopRect
+    }
+
+    VideoOutput {
+        id: output
+        anchors.centerIn: parent
+        // Centered and Tiled show the video at its own size
+        readonly property bool nativeSize: videoComponent.fillMode === Image.Pad || videoComponent.fillMode === Image.Tile
+        width: nativeSize && sourceRect.width > 0 ? sourceRect.width : parent.width
+        height: nativeSize && sourceRect.height > 0 ? sourceRect.height : parent.height
+        z: 1
+
+        fillMode: {
+            switch (videoComponent.fillMode) {
+            case Image.PreserveAspectCrop:
+                return VideoOutput.PreserveAspectCrop;
+            case Image.Stretch:
+                return VideoOutput.Stretch;
+            default:
+                return VideoOutput.PreserveAspectFit;
+            }
+        }
+    }
+
+    Loader {
+        id: blurLoader
+        anchors.fill: parent
+        active: videoComponent.blurEnabled
+        sourceComponent: Item {
+            visible: false // will be rendered by the blur
+            // Like the blurred image, the blurred video covers the whole background
+            ShaderEffectSource {
+                readonly property real scale: Math.max(parent.width / Math.max(1, sourceRect.width), parent.height / Math.max(1, sourceRect.height))
+                anchors.centerIn: parent
+                width: sourceRect.width * scale
+                height: sourceRect.height * scale
+                sourceItem: output
+                sourceRect: output.contentRect
+            }
+        }
+    }
+
+    MediaPlayer {
+        id: player
+        source: videoComponent.source
+        loops: MediaPlayer.Infinite
+        videoOutput: output
+        readonly property bool shouldPause: !videoComponent.forceImageAnimation && activeWindowMonitor.count > 0 && !KWindowSystem.showingDesktop
+        onShouldPauseChanged: shouldPause ? pause() : play()
+        // Pausing a stopped player still shows the first frame
+        Component.onCompleted: shouldPause ? pause() : play()
+    }
+}
